const out = [];
const s = sdk.getState();
const dw = (s.nearbyNpcs || []).find(n => /dark wizard/i.test(n.name || '') && n.reachable !== false);
if (dw) {
  const r = await bot.attack(dw);
  out.push('attack ' + r.success + ' ' + (r.message || ''));
  const t0 = Date.now();
  while (Date.now() - t0 < 30000) {
    const st = sdk.getState();
    if (st.player.hp <= 0 || st.player.isDead) break;
    if (!st.player.inCombat && st.targetIndex !== undefined) break;
    if (!st.player.inCombat) break;
    await sdk.waitForTicks(1);
  }
}
